ivo":"art. 72, § 2º","citacao":"Para os itens I, II, III e IV deverão ser adotados os formulários aprovados pelo DIFE e disponibilizados no sítio da SEESP."}},{"codigo":"carimbos","nome":"Carimbo da nota fiscal (frente e verso)","formato":"doc","arquivo":"lie/modelo-carimbos-2023.doc","fonte":{"documento":"Modelo de carimbos (MESP, 2023)","dispositivo":"frente e verso","nota":"Publicado na vigência da P424; aplica o art. 47, § 1º (nº SLI em todos os comprovantes)."}},{"codigo":"planilha_orcamentaria","nome":"Planilha Orçamentária","formato":"xls","arquivo":"lie/planilha-orcamentaria.xls","fonte":{"documento":"Portaria 424/2020","dispositivo":"art. 7º, § 3º; art. 9º","citacao":"As receitas auferidas em razão do projeto devem estar previstas em orçamento analítico, conforme modelo definido pelo DIFE."}},{"codigo":"planilha_remanejamento","nome":"Planilha de remanejamento e readequação (Modelo I)","formato":"xls","arquivo":"lie/planilha-remanejamento-readequacao.xls","fonte":{"documento":"Portaria 424/2020, na redação da Portaria MESP 33/2025","dispositivo":"art. 57, §§ 1º e 7º","nota":"Remanejamento informado em 5 dias com a documentação atualizada e comprovado na PCF."}},{"codigo":"gru","nome":"Orientações para recolhimento ao Tesouro (GRU)","formato":"pdf","arquivo":"lie/orientacoes-recolhimento-tesouro.pdf","fonte":{"documento":"Orientações para recolhimento de valores ao Tesouro (MESP, 2023)","dispositivo":"p. 1 a 3","nota":"Publicadas na vigência da P424, que manda recolher por GRU sem dar instruções."}}],"regras":[{"codigo":"formularios_obrigatorios","descricao":"Itens I a IV da PCF e da PCP nos formulários do DIFE.","severidade":"bloqueio","fonte":{"documento":"Portaria 424/2020","dispositivo":"art. 72, § 2º; art. 69, § 1º","citacao":"Para os itens I, II, III e IV, deverão ser adotados os formulários"}},{"codigo":"marcador_parcial_final","descricao":"Marcador PARCIAL/FINAL coerente em todas as abas que o têm; A EXECUTAR só na PCP.","severidade":"alerta","fonte":{"documento":"Formulário PCP/PCF 2026 (modelo oficial do MESP)","dispositivo":"células E1/E2, J1/J2, H1/H2, I1/I2, M1/M2, G1/G2 e K1/K2","nota":"Regra do formulário oficial, que a P424 manda usar (arts. 69, § 1º, e 72, § 2º)."}},{"codigo":"numeracao_do_plano","descricao":"Ações numeradas como no Plano de Trabalho; atividade-meio com prefixo M.","severidade":"alerta","fonte":{"documento":"Formulário PCP/PCF 2026 (modelo oficial do MESP)","dispositivo":"instruções das abas","nota":"Instrução do formulário oficial, comum aos dois regimes."}},{"codigo":"responsabilidade_do_contador","descricao":"Contador e proponente respondem civil, penal e administrativamente pelas informações.","severidade":"info","fonte":{"documento":"Portaria 424/2020","dispositivo":"art. 72, § 1º","citacao":"O Contador e Proponente são inteiramente responsáveis pelas informações prestadas, sob pena de responder pelos seus atos cível, penal e administrativamente."}},{"codigo":"arquivos","descricao":"PDF pesquisável com OCR, até 10 MB por arquivo, com as declarações assinadas.","severidade":"alerta","parametros":{"mb":10},"fonte":{"documento":"Portaria 424/2020","dispositivo":"art. 5º, caput; art. 6º, § 5º","citacao":"formato PDF pesquisável OCR, devendo ser inserido no Sistema da Lei de Incentivo ao Esporte, com cada arquivo enviado não excedendo o tamanho superior a 10 MB.","nota":"Regra escrita para a apresentação do projeto; estendida à prestação por cautela."}}],"fonte":{"documento":"Portaria 424/2020","dispositivo":"arts. 69, 71 e 72"}},"posEnvio":{"resultados":[{"resultado":"aprovada","descricao":"Aplicação regular e avaliação técnica satisfatória.","fonte":{"documento":"Portaria 424/2020","dispositivo":"art. 83, I","citacao":"aprovada quando os recursos tiverem aplicação regular e a execução do projeto tiver avaliação técnica satisfatória"}},{"resultado":"aprovada_ressalvas","descricao":"Contas regulares e avaliação técnica insatisfatória, sem prejuízo ao erário nem descumprimento do objeto.","fonte":{"documento":"Portaria 424/2020","dispositivo":"art. 83, II","citacao":"aprovada com ressalvas quando, apesar de regulares as contas, a execução do projeto tiver obtido avaliação técnica insatisfatória, desde que não resulte em prejuízo ao erário ou descumprimento do objeto"}},{"resultado":"aprovada_parcialmente","descricao":"Avaliação técnica satisfatória, com irregularidades nas contas e prejuízo ao erário.","fonte":{"documento":"Portaria 424/2020","dispositivo":"art. 83, III","citacao":"aprovada parcialmente quando, apesar da execução do projeto tiver obtido avaliação técnica satisfatória, forem identificadas irregularidades nas contas, resultando em prejuízo ao erário"}},{"resultado":"reprovada","descricao":"Contas irregulares no Parecer de Avaliação Final, qualquer que seja o resultado técnico.","fonte":{"documento":"Portaria 424/2020","dispositivo":"art. 83, IV","citacao":"reprovada quando, independentemente do resultado do relatório quanto ao cumprimento do objeto e execução física do projeto, tenha as contas consideradas irregulares no Parecer de Avaliação Final."}}],"devolucao":{"descricao":"GRU: saldo na PCF, reprovação em 45 dias da ciência e ressalva por cumprimento parcial ou arquivamento em 30 dias, com os rendimentos; despesa fora da vigência é ressarcida, sem multa.","atualizacao":"IN TCU 71/2012.","gru":[{"unidadeGestora":"180076","gestao":"00001","codigo":"18004-1","referencia":"Número do processo, sem caracteres especiais","fonte":{"documento":"Orientações para recolhimento de valores ao Tesouro (MESP, 2023)","dispositivo":"p. 1 a 3","aConfirmar":true,"nota":"Dados do Tesouro, não da P424; valem para os dois regimes enquanto o MESP não publicar outros. O exemplo do próprio PDF mostra UG 180002; UG e código ficam configuráveis."}}],"fonte":{"documento":"Portaria 424/2020","dispositivo":"art. 84, caput e §§ 3º e 4º; art. 46; art. 72, VII","citacao":"sob pena de ressarcimento e demais penalidades cabíveis."}},"regras":[{"codigo":"duas_analises","descricao":"Análise técnica pela DPPIE (objeto, divulgação, acessibilidade) e financeira pela CGPC (Parecer de Avaliação Final).","severidade":"info","fonte":{"documento":"Portaria 424/2020","dispositivo":"arts. 75, 76, 77 e 78","citacao":"emitirá Parecer de Avaliação Final do projeto sugerindo a aprovação, aprovação parcial, aprovação com ressalva ou reprovação"}},{"codigo":"diligencia_pelo_sistema","descricao":"Diligência da PCF pelo sistema eletrônico da LIE, com recebimento acusado em 1 dia útil e 30 dias improrrogáveis para responder; a falta de documentos leva à reprovação e à TCE.","severidade":"alerta","fonte":{"documento":"Portaria 424/2020","dispositivo":"art. 72, §§ 3º e 4º; art. 88, § 1º, II, f","citacao":"As diligências poderão ser solicitadas via sistema eletrônico da Lei de Incentivo ao Esporte, cujo recebimento deverá ser acusado em até 1 (um) dia útil."}},{"codigo":"tce","descricao":"TCE por PC não apresentada, inexecução, desvio, despesa impugnada, uso indevido de rendimentos, saldo não devolvido ou falta de documentos; CADIN e envio ao TCU em 180 dias.","severidade":"info","fonte":{"documento":"Portaria 424/2020","dispositivo":"art. 88, § 1º, I e II, a a f, e § 3º, II; art. 92","citacao":"A TCE deve ser encaminhada ao TCU em até cento em oitenta dias após a sua instauração"}},{"codigo":"prescricao","descricao":"Sanções prescrevem em 5 anos da apresentação da PCF; o ressarcimento não prescreve.","severidade":"info","fonte":{"documento":"Portaria 424/2020","dispositivo":"art. 85","citacao":"Transcorrido o prazo de 5 (cinco) anos, contados da apresentação dos documentos previstos no art. 72 desta Portaria, fica caracterizada a prescrição para aplicação das sanções"}},{"codigo":"multa_vantagem","descricao":"Vantagem indevida: multa de 2 vezes o valor e rescisão com devolução integral.","severidade":"info","fonte":{"documento":"LC 222/2025","dispositivo":"arts. 20 e 21","nota":"Vale pelos projetos da P424 (Portaria MESP 10/2026, art. 102); antes, Lei 11.438/2006, art. 11, II."}},{"codigo":"pcf_fora_do_prazo","descricao":"PCF não apresentada no prazo: o DIFE recolhe ao Tesouro o saldo das contas CAPTAÇÃO e MOVIMENTO, com os rendimentos, e recomenda a TCE; o acesso ao SLI fica suspenso até o saneamento, e o saldo não vai para outro projeto.","severidade":"bloqueio","fonte":{"documento":"Portaria 424/2020","dispositivo":"art. 71, §§ 3º e 4º, na redação da Portaria 638/2021","citacao":"o DIFE recolherá ao Tesouro Nacional o saldo existente à época nas contas CAPTAÇÃO e MOVIMENTO, incluindo rendimentos, e recomendará a instauração de Tomadas de Contas Especial","nota":"A redação original dava 30 dias para apresentar ou recolher. As Portarias 62/2023 e MESP 33/2025 acrescentaram a paralisação dos outros projetos e a volta do acesso depois de sanada a PCF; esses parágrafos não foram conferidos no texto compilado."}}],"fonte":{"documento":"Portaria 424/2020","dispositivo":"arts. 75 a 93 (equivalentes aos arts. 71 a 88 da P10)","citacao":"O parecer de prestação de contas final emitido pelo DIFE juntamente com o processo digitalizado será encaminhado à Coordenação Geral de Prestação de Contas - CGPC"}},"guarda":{"marco":"registro_decisao","quantidade":10,"unidade":"anos","prorrogaParaDiaUtil":false,"descricao":"Originais na sede, à disposição do MESP e dos órgãos de controle, contados da avaliação da PCF.","fonte":{"documento":"Portaria 424/2020","dispositivo":"art. 73; art. 81; art. 51, § 1º","citacao":"deverão ser arquivados na sede do proponente, por no mínimo 10 (dez) anos após a avaliação da Prestação de Contas Final"}}}$regime$::jsonb as p) dados
on conflict (codigo, versao) do nothing;

-- PRONON e PRONAS/PCD — Anexo LXXXVI (anterior) (versão 2)
update public.prestacao_regimes set status = 'obsoleto'
where codigo = 'pronon_pronas_lxxxvi_2017' and versao < 2 and status = 'publicado';

insert into public.prestacao_regimes
  (codigo, versao, nome, area, mecanismo, esfera, orgao, sistema_oficial, norma_referencia,
   vigente_desde, vigente_ate, status, parametros, fontes, checklist_envio, modelos_saida, publicado_em)
select
  'pronon_pronas_lxxxvi_2017', 2, 'PRONON e PRONAS/PCD — Anexo LXXXVI (anterior)', 'saude', 'saude',
  'federal', 'Ministério da Saúde', 'SIPAR (protocolo)', 'Lei 12.715/2012; Decreto 7.988/2013; Anexo LXXXVI da PRC GM/MS 5/2017 (origem na PRT GM/MS 1.550/2014), revogado pela Portaria GM/MS 8.031/2025',
  '2017-09-28'::date, '2025-09-07'::date, 'publicado',
  p, coalesce(p->'fontes', '[]'), coalesce(p->'envio'->'documentos', '[]'), coalesce(p->'envio'->'modelos', '[]'), now()
from (select $regime${"codigo":"pronon_pronas_lxxxvi_2017","versao":2,"nome":"PRONON e PRONAS/PCD — Anexo LXXXVI (anterior)","area":"saude","mecanismo":"saude","esfera":"federal","orgao":"Ministério da Saúde","sistemaOficial":"SIPAR (protocolo)","normaReferencia":"Lei 12.715/2012; Decreto 7.988/2013; Anexo LXXXVI da PRC GM/MS 5/2017 (origem na PRT GM/MS 1.550/2014), revogado pela Portaria GM/MS 8.031/2025","vigenteDesde":"2017-09-28","identificadorOficial":{"tipo":"nup","rotulo":"Nº do processo (SIPAR)"},"fontes":[{"documento":"PRC GM/MS 5/2017 compilada (Anexo LXXXVI, revogado)","url":"https://bvsms.saude.gov.br/bvs/saudelegis/gm/2017/prc0005_03_10_2017_comp.html"},{"documento":"Portaria GM/MS 8.031/2025 (revoga o Anexo LXXXVI)","url":"https://www.in.gov.br/web/dou/-/portaria-gm/ms-n-8.031-de-5-de-setembro-de-2025-653608142"},{"documento":"Lei 12.715/2012 (Planalto)","url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2012/lei/l12715.htm"}],"aplicabilidade":{"criterio":"aprovacao_projeto","desde":"2017-09-28","ate":"2025-09-07","descricao":"Projetos aprovados na vigência da PRC 5/2017, para os atos praticados até 07/09/2025. Desde abr/2026 o MS decide os atos desses projetos pelo Anexo LXXXVI-A; as obrigações do Termo de Compromisso assinado continuam. Projetos das Portarias 875/2013 e 1.550/2014 não estão modelados.","sucede":[],"fonte":{"documento":"Manual de análise contábil e financeira PRONON e PRONAS/PCD (FNS, 2019), Anexo III","dispositivo":"seção 4.0, p. 6","nota":"Corte final pela Portaria GM/MS 8.031/2025, arts. 4º e 5º; a prática posterior está nas Portarias SE/MS 922 a 983/2026."}},"prazos":{"prestacaoFinal":{"descricao":"Prestação no ano seguinte ao último exercício com execução, até 30/04, com demonstrações contábeis e auditoria","responsavel":"proponente","marco":"fim_exercicio","quantidade":4,"unidade":"meses","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, parágrafo único"}},"prestacaoAnual":{"descricao":"Demonstrações contábeis, auditoria e relatório de execução até 30/04 de cada ano de execução","responsavel":"proponente","marco":"fim_exercicio","quantidade":4,"unidade":"meses","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, parágrafo único"}},"respostaDiligencia":{"descricao":"Sanar irregularidade ou omissão na prestação (notificação única)","responsavel":"proponente","marco":"ciencia_diligencia","quantidade":30,"unidade":"dias_corridos","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 97, § 3º"}},"analisePrestacao":{"descricao":"Análise da prestação; o FNS analisava a parte financeira","responsavel":"orgao","marco":"envio_prestacao","quantidade":90,"unidade":"dias_corridos","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 96"}},"recurso":{"descricao":"Recurso protocolado na SE/MS, que o envia à autoridade recorrida em 5 dias; mantida a decisão, sobe à autoridade superior em 5 dias","responsavel":"proponente","marco":"ciencia_decisao","quantidade":10,"unidade":"dias_corridos","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 103, caput e § 2º; art. 113","citacao":"A instituição poderá interpor recurso perante a SE/MS, que encaminhará à autoridade recorrida, no prazo máximo de 5 (cinco) dias, contados de seu recebimento.","nota":"O anexo não fixa prazo para recorrer da prestação; pelo art. 113 vale a Lei 9.784/1999, que dá 10 dias (art. 59)."}},"devolucao":{"descricao":"Recolher por GRU, inclusive na reprovação parcial ou final, depois da notificação do MS","responsavel":"proponente","marco":"ciencia_decisao","quantidade":30,"unidade":"dias_corridos","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 88, VII e § 1º"}},"devolucaoSaldo":{"descricao":"Recolher por GRU os saldos das contas Captação e Movimento, com rendimentos, depois da notificação do MS","responsavel":"proponente","marco":"ciencia_diligencia","quantidade":30,"unidade":"dias_corridos","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 88, V, VI e § 1º"}},"readequacaoCaptacao":{"descricao":"Apresentar a readequação para menor (60% a 99,99% captado) ou para maior (até 20%)","responsavel":"proponente","marco":"fim_captacao","quantidade":30,"unidade":"dias_corridos","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 69, caput, e art. 70, caput (texto retificado no DOU de 12/03/2020)","citacao":"art. 69: “desde que tenham sido captados pelo menos 60% dos recursos, a instituição enviará, no prazo de 30 (trinta) dias contados do término do período de captação de recursos, readequação”; art. 70: “readequação para maior do orçamento do projeto aprovado, em até 20% (vinte por cento), a critério do Ministério da Saúde”","nota":"O prazo de captação do art. 68, § 3º (90 + 30 dias), foi revogado pela PRT GM/MS 3.314/2024; vale o da portaria de autorização."}},"notificacaoMonitoramento":{"descricao":"Responder a notificação do monitoramento","responsavel":"proponente","marco":"ciencia_diligencia","quantidade":20,"unidade":"dias_corridos","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 89, § 5º"}},"recursoInabilitacao":{"descricao":"Recorrer ao Ministro da inabilitação","responsavel":"proponente","marco":"ciencia_decisao","quantidade":15,"unidade":"dias_corridos","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 107","citacao":"Caberá recurso para o Ministro de Estado da Saúde, da decisão de que trata o art. 106, § 2º , II, no prazo de 15 (quinze) dias, contado da notificação da instituição destinatária."}}},"prestacaoParcial":{"modalidades":["periodica"],"descricao":"Prestação anual até 30/04 de cada ano de execução, com demonstrações contábeis, relatório de auditoria independente e relatório de execução; a final no ano seguinte ao último exercício.","prazo":"prestacaoAnual","regras":[{"codigo":"auditoria_anual","descricao":"Demonstrações contábeis e financeiras com parecer conclusivo de auditoria independente registrada no CRC, todo ano.","severidade":"bloqueio","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, caput e parágrafo único","citacao":"art. 92: “demonstrações contábeis e financeiras, submetidas a parecer conclusivo de auditoria independente, realizada por instituição credenciada perante o respectivo Conselho Regional de Contabilidade (CRC)”; parágrafo único: “serão apresentados anualmente até o dia 30 de abril de cada ano de execução o projeto”","nota":"Também no Decreto 7.988/2013, art. 22, parágrafo único."}},{"codigo":"excecao_2025","descricao":"A prestação do exercício 2025 vai até 31/05/2026; os demais exercícios seguem 30/04.","severidade":"info","fonte":{"documento":"Portaria SE/MS 928/2026","dispositivo":"art. 4º","nota":"Ato posterior à revogação do anexo; o MS o aplicou a todos os projetos executados em 2025, inclusive os antigos."}},{"codigo":"relatorio_de_monitoramento","descricao":"O órgão técnico acompanha a execução, com acesso a documentos e locais, auditorias e vistorias; as diligências ficam no relatório de monitoramento do processo.","severidade":"info","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 89, §§ 2º e 4º; art. 16, IV","citacao":"As diligências previstas no § 2º serão registradas em relatório de monitoramento do projeto, que integrará os autos do processo administrativo."}}],"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, parágrafo único"}},"orcamento":{"estrutura":{"niveis":["Natureza da despesa","Categoria de gasto","Item"],"descricao":"Orçamento detalhado com todos os custos, a natureza das despesas e as categorias dos gastos.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 27"}},"grupos":[{"codigo":"execucao","rotulo":"Custos do projeto","descricao":"Custos de execução do projeto, por natureza da despesa e categoria de gasto; no modelo, os bens de capital aparecem como custos indiretos.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 27; Anexo 6 (modelo de orçamento)"}},{"codigo":"administracao","rotulo":"Despesas administrativas","descricao":"Escritório, aluguel, correios, transporte administrativo, telefone, água, luz, internet e honorários administrativos, contábeis e advocatícios, detalhados no orçamento.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 28","citacao":"Serão admitidas como despesas administrativas:"}},{"codigo":"elaboracao","rotulo":"Elaboração e captação","descricao":"Elaboração da proposta e captação de recursos.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 27, §§ 2º e 3º","citacao":"As despesas referentes aos serviços de elaboração do projeto e de captação de recursos deverão ser detalhadas na planilha de custos do projeto, sendo obrigatório o seu destaque em relação aos demais itens de despesas."}}],"bases":{"valor_projeto":{"descricao":"Valor do projeto: o orçamento inteiro.","soma":"todos","exceto":[],"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 27, caput; Anexo 6 do Anexo LXXXVI (modelo de orçamento)","citacao":"art. 27: “O projeto deverá apresentar orçamento detalhado, contendo todos os custos envolvidos para alcance dos objetivos”; Anexo 6: “VALOR DO PROJETO: R$ XXX”"}},"valor_total_projeto":{"descricao":"Montante global do projeto.","soma":"todos","exceto":[],"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 27, § 3º","citacao":"desde que as despesas somadas não ultrapassem 5% (cinco por cento) do valor total previsto para o projeto, limitada ao teto de R$ 50.000,00 (cinquenta mil reais)"}}},"tetos":[{"codigo":"elaboracao_captacao","descricao":"Elaboração do projeto e captação","grupos":["elaboracao"],"percentual":5,"base":"valor_total_projeto","teto":50000,"severidade":"bloqueio","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 27, § 3º","nota":"Soma até 5% do valor total previsto, com teto de R$ 50 mil."}}],"regras":[{"codigo":"precos_de_referencia","descricao":"Preços pelo SIGEM, BPS, SIASG, SINAPI ou outros sistemas de referência; fora deles, a opção mais econômica entre 3 orçamentos ou justificativa circunstanciada.","severidade":"alerta","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 51, caput e §§ 1º e 2º; arts. 35, 39 e 42","citacao":"art. 51: “levará em conta os valores constantes do SIGEM, do BPS, do Sistema Integrado de Administração de Serviços Gerais (SIASG), do SINAPI, além de outros sistemas de informação”; art. 51, § 1º: “no mínimo, 3 (três) orçamentos com preços praticados no mercado”"}},{"codigo":"equipamentos","descricao":"Equipamentos com viabilidade e sustentabilidade, normas da Anvisa e preço pelo SIGEM.","severidade":"alerta","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"arts. 36, 37 e 39","citacao":"art. 36: “de forma a permitir ao analista técnico avaliar a viabilidade técnica de instalação e operação dos equipamentos, bem como a sustentabilidade desses”; art. 39: “deverá ser consultado o Sistema de Informação e Gerenciamento de Equipamentos e Materiais (SIGEM) do Fundo Nacional de Saúde”","nota":"O anexo anterior também pedia que os itens constassem das relações do FNS, salvo em pesquisa (art. 36)."}},{"codigo":"medicamentos","descricao":"Medicamentos da RENAME; oncológicos com registro na Anvisa.","severidade":"alerta","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 40, § 1º","citacao":"“deverão estar listados na Relação Nacional de Medicamentos Essenciais (RENAME), exceto quando se tratar de medicamento utilizado no tratamento do câncer”; “que deverão ser registrados na ANVISA”"}},{"codigo":"opm","descricao":"Órteses, próteses e outros produtos para a saúde em qualquer projeto, ligados ao objeto, com preço pelo BPS e pelo SIASG.","severidade":"alerta","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 40, caput; arts. 41 e 42","citacao":"Os projetos poderão prever a aquisição de medicamentos, kits diagnósticos, materiais médico-hospitalares, órteses, próteses e de outros produtos para saúde, observando o seu objeto."}},{"codigo":"prazo_de_execucao","descricao":"Execução em até 24 meses; pesquisa em até 36.","severidade":"alerta","parametros":{"meses":24,"mesesPesquisa":36},"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 26, § 1º","citacao":"O prazo para execução do projeto poderá ser de até 24 (vinte e quatro) meses, exceto quando se tratar de projetos de pesquisa, hipótese em que o prazo de execução poderá ser de até 36 (trinta e seis) meses."}},{"codigo":"despesas_administrativas","descricao":"Despesas administrativas indispensáveis entram detalhadas no orçamento, sem teto percentual; taxa de administração é vedada.","severidade":"info","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 28; art. 44, I","citacao":"a título de taxa de administração ou similar"}}]},"alteracoes":{"janela":{"aPartirDe":"assinatura_termo","ate":"fim_execucao","descricao":"Durante a execução, que começa com o Termo de Compromisso assinado e publicado e a liberação da Conta Captação para a Movimento; alterações do plano vão ao órgão competente, que tem 10 dias para se manifestar.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"arts. 26, § 2º, 65, 84 e 87","citacao":"O órgão do Ministério da Saúde competente terá o prazo de 10 (dez) dias para se manifestar formalmente acerca da alteração"}},"tipos":{"remanejamento":{"permitido":true,"classificacao":"formal","condicoes":[],"requisitos":[{"tipo":"tetos","severidade":"bloqueio","descricao":"Depois do remanejamento, elaboração e captação continuam dentro do teto, o único do regime.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 27, § 3º; art. 44, V","citacao":"art. 44, V: “com ações e serviços de captação que excedam o limite estabelecido no art. 27, § 3º”"}}],"orientacoes":[{"codigo":"parecer_do_orgao_tecnico","descricao":"Remanejamento de rubricas depende de parecer conclusivo do órgão técnico; a alteração do plano vai ao órgão competente, que se manifesta em 10 dias.","severidade":"bloqueio","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 16, III; art. 87","citacao":"art. 16, III: “avaliar pedidos de remanejamento de rubricas e adequação do projeto em função de captação inferior ou superior ao inicialmente planejado e aprovado, emitindo parecer conclusivo”","nota":"O anexo não prevê Termo de Apostilamento."}}],"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 16, III; art. 87","citacao":"art. 16, III: “avaliar pedidos de remanejamento de rubricas”; art. 87: “Quaisquer alterações no Plano de Trabalho do projeto autorizado serão submetidas à apreciação do órgão do Ministério da Saúde competente, com justificativas necessárias.”"}},"complementacao":{"permitido":true,"classificacao":"formal","condicoes":[],"requisitos":[{"tipo":"acumulado_maximo","percentual":20,"base":"valor_homologado_execucao","severidade":"bloqueio","descricao":"Captação a maior com readequação de até 20% do aprovado.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 70"}},{"tipo":"tetos","severidade":"bloqueio","descricao":"A readequação respeita os tetos.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 27, § 3º"}}],"orientacoes":[{"codigo":"pedido_em_30_dias","descricao":"Pedido em 30 dias do fim da captação.","severidade":"alerta","parametros":{"dias":30},"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 70, caput","citacao":"A instituição poderá enviar, no prazo de 30 (trinta) dias contados do término do período de captação de recursos, readequação para maior do orçamento do projeto aprovado"}},{"codigo":"excedente_recolhido","descricao":"O que passar de 120% do aprovado é recolhido.","severidade":"alerta","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 70, caput e § 4º; art. 88, V","citacao":"art. 70: “em até 20% (vinte por cento)”; art. 70, § 4º: “Os recursos captados remanescentes serão recolhidos na forma do art. 88.”"}},{"codigo":"portaria_da_se","descricao":"A readequação sai em portaria da SE/MS; a prorrogação é decidida pelo MS uma única vez. O anexo não fala em termo aditivo.","severidade":"info","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"arts. 69, 70, 86 e 87","citacao":"art. 86: “O Ministério da Saúde decidirá sobre eventual pedido de prorrogação de prazo para a execução do projeto, uma única vez”","nota":"O Termo de Compromisso assinado pode prever o aditivo; confira o do projeto."}}],"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 70"}},"reducao":{"permitido":true,"classificacao":"formal","condicoes":[],"requisitos":[{"tipo":"captado_minimo","percentual":60,"base":"valor_homologado_execucao","severidade":"bloqueio","descricao":"Com 60% ou mais captado, readequação para menor; 100% para executar sem readequar.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"arts. 68 e 69"}}],"orientacoes":[{"codigo":"pedido_em_30_dias","descricao":"Readequação para menor em 30 dias do fim da captação; a execução só começa depois de aprovada (SE em 10 dias, secretaria em 30, portaria em 10).","severidade":"alerta","parametros":{"dias":30},"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 69, caput e §§ 2º a 4º (texto retificado no DOU de 12/03/2020)","citacao":"art. 69: “no prazo de 30 (trinta) dias contados do término do período de captação de recursos, readequação das ações previstas no projeto aprovado ao valor total obtido na captação, mediante aprovação prévia do Ministério da Saúde”; § 3º: “terá o prazo de 30 (trinta) dias do recebimento da proposta de readequação para emitir parecer técnico conclusivo”"}}],"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"arts. 68 e 69"}},"inclusao":{"permitido":true,"classificacao":"formal","condicoes":[],"requisitos":[{"tipo":"tetos","severidade":"alerta","descricao":"Com o item novo, os grupos continuam dentro dos tetos.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 27, § 3º; art. 44, V","citacao":"desde que as despesas somadas não ultrapassem 5% (cinco por cento) do valor total previsto para o projeto, limitada ao teto de R$ 50.000,00 (cinquenta mil reais)","nota":"No regime anterior o único teto é o de elaboração e captação."}}],"orientacoes":[],"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 87","citacao":"Quaisquer alterações no Plano de Trabalho do projeto autorizado serão submetidas à apreciação do órgão do Ministério da Saúde competente, com justificativas necessárias.","nota":"O MS tinha 10 dias para se manifestar (art. 87, parágrafo único)."}}},"alertasPorItem":[],"prazoAnalise":null,"silencioAprova":false,"regras":[{"codigo":"uso_de_rendimentos","descricao":"Rendimentos da Conta Movimento pagam ações do projeto a critério da instituição, que justifica a escolha na prestação; despesa administrativa, elaboração ou captação só com autorização expressa do MS.","severidade":"alerta","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 82, § 3º, II, b e c, na redação da PRT GM/MS 751/2020","citacao":"serão utilizados em ações do projeto aprovado para a obtenção do melhor resultado para a execução do projeto, a critério da instituição, que deverá justificar a escolha realizada na apresentação da prestação de contas"}},{"codigo":"remanejamento_entre_projetos","descricao":"Remanejamento entre Contas Captação: mesmo CNPJ, programa e ano fiscal, depois do fim da captação e antes da readequação; o beneficiário recebe até 20% acima do aprovado, e o que passa do art. 70 pode sair em qualquer fase da execução do cedente. A SE/MS publica em 20 dias.","severidade":"alerta","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"arts. 75, 76 e 78 (texto retificado no DOU de 12/03/2020)","citacao":"podendo o remanejamento ocorrer em qualquer fase de execução do projeto cedente"},"parametros":{"percentual":20}},{"codigo":"prorrogacao","descricao":"Pedido de prorrogação até 60 dias antes do fim do prazo.","severidade":"alerta","parametros":{"diasAntes":60},"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 86"}}],"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 69, caput; art. 87, parágrafo único","citacao":"art. 69: “mediante aprovação prévia do Ministério da Saúde”; art. 87: “terá o prazo de 10 (dez) dias para se manifestar formalmente acerca da alteração”","nota":"O prazo de 10 dias do MS não gera aprovação tácita."}},"fornecedores":{"limites":[],"partesRelacionadas":{"descricao":"É vedado captar de entidades vinculadas à proponente e dar ao doador vantagem em razão da doação; o anexo não diz que expor a marca do doador é vantagem indevida.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 66; arts. 44, IV, 105, X, e 110","citacao":"É vedada a captação de recursos de entidades vinculadas à instituição proponente."}},"regras":[{"codigo":"vantagem_ao_doador","descricao":"Despesa que gere vantagem ao doador é vedada; com dolo, multa de 2 vezes a vantagem.","severidade":"bloqueio","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 44, IV; art. 110","citacao":"art. 44, IV: “que resultarem em vantagem financeira ou material para o doador, nos termos da Lei nº 12.715, de 2012”","nota":"A multa de 2 vezes a vantagem vem da Lei 12.715/2012, que vale para qualquer projeto."}},{"codigo":"unidade_executora","descricao":"A instituição executa o projeto e não transfere as atividades principais.","severidade":"bloqueio","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 89, § 3º","citacao":"“A unidade executora do projeto será a própria instituição”; “não podendo atribuir a terceiros as atividades principais objeto do projeto”"}},{"codigo":"intermediacao","descricao":"Intermediação é vedada, salvo a contratação de elaboração do projeto e de captação.","severidade":"bloqueio","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 81; art. 46","citacao":"art. 81: “Nenhuma aplicação dos recursos poderá ser efetuada mediante intermediação. Parágrafo Único. Não configura intermediação a contratação de serviços de:”","nota":"Exceções: elaboração do projeto e captação (art. 81, I e II)."}},{"codigo":"equipe_ligada_a_acao","descricao":"Não se pagam profissionais que já atuam na instituição, salvo aumento de carga horária; ninguém é contratado para atividade sem relação com o objeto.","severidade":"alerta","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 24, §§ 1º e 2º","citacao":"§ 1º: “Os projetos não poderão solicitar o custeio dos serviços já realizados na instituição, tampouco o pagamento de profissionais que já atuam no local, exceto nos casos em que houver a necessidade e possibilidade de se aumentar a carga horária”; § 2º: “Em nenhuma hipótese será admitida contratação de profissionais para execução de atividades que não apresentem relação com o objeto do projeto.”"}}],"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"arts. 45, 66, 81 e 89, § 3º","citacao":"art. 66: “É vedada a captação de recursos de entidades vinculadas à instituição proponente.”"}},"contas":{"contas":[{"tipo":"captacao","descricao":"Conta Captação, bloqueada, que recebe as doações","abertaPor":"orgao"},{"tipo":"movimento","descricao":"Conta Movimento, de livre movimentação, só para despesas do projeto","abertaPor":"orgao"}],"bancos":["Banco do Brasil"],"descricao":"Duas contas por projeto, abertas pelo MS em instituição financeira oficial; a instituição autoriza o banco, de forma irrevogável, a cumprir as ordens do MS.","tarifas":{"regra":"norma_silente","descricao":"O regime anterior não trata de tarifas bancárias.","fonte":{"documento":"Manual de análise contábil e financeira PRONON e PRONAS/PCD (FNS, 2019), Anexo III","dispositivo":"seção 3 (contas)"}},"liberacao":{"descricao":"A execução só começa com 100% captado e o Termo de Compromisso assinado e publicado; de 60% a 99,99%, readequação para menor; abaixo de 60%, indeferimento. Rendimentos não contam.","percentualMinimo":100,"base":"valor_aprovado_execucao","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"arts. 65, 68 (caput e § 2º), 69, 82, § 3º, I, b, e 88, IV","citacao":"art. 68: “Somente poderão ser iniciadas as execuções dos projetos depois de captados 100% (cem por cento) dos recursos previstos nos respectivos orçamentos.”; art. 82, § 3º, I, b: “não serão computados no cálculo dos montantes captados para fins de apuração da captação integral ou captação mínima”"}},"rendimentos":{"aplicacao":"obrigatoria","contamComoCaptado":false,"uso":"Aplicação automática em poupança; na Conta Movimento, opção entre poupança e fundo de curto prazo. Rendimentos da Conta Captação não contam para os 60% nem para os 100% e voltam com o saldo.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 82, caput e § 3º, I, b, na redação da PRT GM/MS 751/2020","citacao":"não serão computados no cálculo dos montantes captados para fins de apuração da captação integral ou captação mínima","nota":"A redação original pedia fundo de curto prazo ou operação de mercado aberto lastreada em título público federal."}},"saldo":{"descricao":"Saldos das contas Captação e Movimento, com rendimentos, recolhidos à Conta Única do Tesouro por GRU em 30 dias da notificação, sem prejuízo ao doador; recursos não usados podem voltar da Conta Movimento para a Captação.","prazo":"devolucaoSaldo","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 88 e § 1º; art. 92, VIII"}},"regras":[{"codigo":"captacao_depois_da_publicacao","descricao":"Captação só depois da publicação da portaria de aprovação e autorização, no prazo fixado nela.","severidade":"bloqueio","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 60, caput; art. 55, V","citacao":"Os recursos financeiros oriundos de doação somente poderão ser captados após a publicação da portaria de aprovação de projeto e de autorização para captação de recursos de que trata o art. 54.","nota":"Os 90 + 30 dias do art. 68, § 3º, foram revogados pela PRT GM/MS 3.314/2024."}},{"codigo":"doacao_em_bens","descricao":"Doações em bens, comodato ou insumos exigem recibos antes da liberação; insumos de doador PJ, com nota, validade de 12 meses e preço até o orçado.","severidade":"bloqueio","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 68, § 4º; art. 74, caput e §§ 1º e 2º","citacao":"art. 68, § 4º: “estará condicionada à apresentação dos recibos nos casos de doações previstas nos incisos II a V do art. 57”; art. 74: “somente poderão ser feitas por pessoas jurídicas e com apresentação de nota fiscal dos produtos doados”; § 1º: “não poderá ser inferior a 12 (doze) meses”","nota":"O anexo anterior também admitia doação por realização de despesas com reformas (art. 57, IV; art. 73)."}},{"codigo":"captacao_acima","descricao":"Acima de 120% do aprovado, o excedente é desconsiderado e recolhido.","severidade":"alerta","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 70, caput e § 4º; art. 88, V","citacao":"art. 70: “em até 20% (vinte por cento)”; art. 70, § 4º: “Os recursos captados remanescentes serão recolhidos na forma do art. 88.”"}},{"codigo":"contas_bloqueadas","descricao":"A Conta Captação é bloqueada no fim da captação ou com 100%; as contas são encerradas depois da vigência do Termo.","severidade":"info","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 59, §§ 6º e 7º","citacao":"§ 6º: “Após o prazo de captação ou quando for captada a integralidade dos recursos previstos no projeto, o Ministério da Saúde providenciará o bloqueio da Conta Captação.”; § 7º: “o encerramento de contas após o término da vigência do Termo de Compromisso”"}},{"codigo":"recursos_publicos","descricao":"Os recursos são públicos, impenhoráveis e não integram o patrimônio da entidade.","severidade":"info","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 89, caput","citacao":"As doações captadas pelas instituições no âmbito do Pronon e do Pronas/PCD são recursos públicos","nota":"A impenhorabilidade vem do CPC, art. 833, IX."}},{"codigo":"regularidade","descricao":"Regularidade fiscal, tributária e previdenciária mantida o tempo todo e exigível a qualquer tempo (FGTS, INSS, CND conjunta, CEPIM e CADIN); a perda leva ao descredenciamento, e o MS pode bloquear as contas.","severidade":"alerta","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 17, VII, VIII e § 3º; art. 22, IV; art. 59, § 5º, II","citacao":"A regularidade fiscal, tributária e com a seguridade social deverá ser mantida por todo o período de execução dos projetos, podendo a sua comprovação ser exigida a qualquer tempo pelo Ministério da Saúde."}},{"codigo":"recibo_por_deposito","descricao":"Recibo por depósito em 3 vias, com ofício ao MS em 20 dias.","severidade":"alerta","parametros":{"dias":20},"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 64"}}],"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 59, caput e § 1º; art. 61","citacao":"art. 59, § 1º: “serão vinculadas a cada projeto e serão abertas pelo Ministério da Saúde em instituição financeira oficial”; art. 61: “a instituição autorizará a instituição financeira oficial, em caráter irrevogável e irretratável, a cumprir as determinações do Ministério da Saúde relativas às movimentações financeiras”"}},"pagamentos":{"meiosPermitidos":null,"meiosVedados":[],"descricao":"O regime não restringe o meio de pagamento e cita cheques entre os documentos; cada débito da Conta Movimento corresponde a um comprovante.","documentoFiscal":[{"codigo":"em_nome_da_instituicao","descricao":"Documentos emitidos única e exclusivamente em nome da instituição.","severidade":"bloqueio","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 95"}},{"codigo":"sipar_e_projeto","descricao":"Número do processo, registro no SIPAR, nome do projeto e discriminação em faturas, recibos, notas e cheques; sem como incluir, o representante legal declara no próprio documento.","severidade":"bloqueio","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 95, §§ 1º e 2º"}}],"regras":[{"codigo":"um_comprovante_por_debito","descricao":"Cada débito da Conta Movimento corresponde a um comprovante de regular aplicação.","severidade":"bloqueio","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 83"}}],"fonte":{"documento":"Manual de análise contábil e financeira PRONON e PRONAS/PCD (FNS, 2019), Anexo III","dispositivo":"seção 3 (meios de pagamento)"}},"despesas":{"periodo":{"descricao":"Da celebração do Termo de Compromisso ao fim do prazo de execução, sob pena de ressarcimento.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 84"}},"vedadas":[{"codigo":"taxa_administracao","descricao":"Taxa de administração","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 44, I","citacao":"a título de taxa de administração ou similar"}},{"codigo":"consultoria_de_servidor","descricao":"Pagamento a servidor público por consultoria","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 44, II","citacao":"em benefício de servidor ou empregado público, integrante do quadro de pessoal de órgão ou entidade pública da administração direta ou indireta de qualquer esfera governamental, por serviços de consultoria ou assistência técnica"}},{"codigo":"clube_de_servidores","descricao":"Clubes e associações de servidores","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 44, III","citacao":"em favor de clubes e associações de servidores públicos ou entidades congêneres"}},{"codigo":"vantagem_ao_doador","descricao":"Vantagem ao doador","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 44, IV","citacao":"que resultarem em vantagem financeira ou material para o doador, nos termos da Lei nº 12.715, de 2012"}},{"codigo":"festas_bufe","descricao":"Festas e bufê, salvo refeições de profissionais e ações educativas","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 44, VI","citacao":"com recepções, festas, coquetéis, serviços de bufê ou similares, excetuados os gastos com refeições dos profissionais ou com ações educativas"}},{"codigo":"primeira_classe","descricao":"Passagem de primeira classe ou executiva, salvo necessidade justificada de pessoa com deficiência ou mobilidade reduzida","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 44, VII","citacao":"referentes à compra de passagens em primeira classe ou classe executiva, salvo em caso de necessidade justificada, para pessoas com deficiência ou mobilidade reduzida"}},{"codigo":"taxas_multas_juros","descricao":"Taxas bancárias, multas, juros e correção","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 44, VIII","citacao":"com taxas bancárias, multas, juros ou correção monetária, inclusive referentes a pagamentos ou recolhimentos fora dos prazos"}},{"codigo":"acao_ja_no_sus","descricao":"Ações médico-assistenciais que a instituição já executa pelo SUS","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 44, IX; art. 24","citacao":"para custeio de ações e serviços médico-assistenciais, já executados pelo proponente para atenção às pessoas no âmbito do SUS"}},{"codigo":"antes_do_termo","descricao":"Fato gerador anterior à vigência do Termo, salvo elaboração e captação","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 68, § 1º; art. 84","citacao":"A instituição não poderá ressarcir-se de despesas efetuadas em data anterior à celebração do Termo de Compromisso, exceto para captação de recursos e elaboração de projeto.","nota":"O marco é a celebração do Termo; despesa depois do prazo de execução também é ressarcida (art. 84)."}},{"codigo":"obras","descricao":"Ampliação e construção de imóveis","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 34","citacao":"ficando vedada a realização de investimentos com ampliação e construção de imóveis"}},{"codigo":"compra_centralizada","descricao":"Medicamentos de compra centralizada pelo MS","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 40, § 3º","citacao":"Não será permitida a previsão de medicamentos cuja aquisição seja realizada de forma centralizada pelo Ministério da Saúde."}}],"regras":[{"codigo":"encargos_da_instituicao","descricao":"Encargos trabalhistas da equipe são responsabilidade exclusiva da instituição, sem vínculo com a administração.","severidade":"info","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 94; art. 89, § 3º","citacao":"art. 94: “É responsabilidade da instituição, efetuar a retenção e os recolhimentos de impostos e contribuições que incidirem sobre os recursos movimentados, serviços contratados e obrigações decorrentes de relações de trabalho.”"}},{"codigo":"sem_sobreposicao_sus","descricao":"Metas e produção não repetem o que é contratado pelo SUS ou usado para o CEBAS.","severidade":"alerta","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 24, caput, I e II","citacao":"“não poderá ocorrer em prejuízo de suas atividades prestadas ao SUS, não podendo compreender o quantitativo executado ou em execução”; II: “para obtenção do Certificado de Entidade Beneficente de Assistência Social”"}},{"codigo":"obras_com_requisitos","descricao":"Reformas (conservação, manutenção e reparos, sem mudar a área) com declaração do responsável técnico e custo pelo SINAPI ou, na falta dele, por 3 propostas.","severidade":"alerta","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"arts. 34 e 35; art. 2º, XX","citacao":"somente será permitida a realização de despesas com obras em imóveis, no âmbito do Pronon e do Pronas/PCD, se referentes a reformas"}}],"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"arts. 27, 28, 29 a 44, 68, § 1º, e 84","citacao":"art. 44: “É vedada a previsão de despesas:”"}},"porte":{"lacuna":"nao_se_aplica","motivo":"O anexo não classifica projetos por porte: toda prestação passa pela análise contábil e financeira do FNS e pelo parecer do órgão técnico; a financeira só é dispensada quando o objeto é integralmente descumprido.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 96, caput e § 1º; art. 97, § 2º","citacao":"Em caso de descumprimento integral do objeto, atestado no parecer de avaliação técnica, fica dispensada a análise financeira da prestação de contas."}},"objeto":{"descricao":"O parecer confirma os documentos do art. 92, compara resultados esperados e atingidos e aponta metas descumpridas; o FNS analisa o contábil e o financeiro de toda prestação; produção médico-assistencial no CMD (antes, no CIHA).","regras":[{"codigo":"metas_resultados","descricao":"Resultados esperados × atingidos, objetivos previstos × alcançados e custos estimados × reais; metas ou atividades descumpridas levam à devolução correspondente.","severidade":"bloqueio","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, parágrafo único, I; art. 97, II e § 1º","citacao":"art. 92, I: “relatório de cumprimento do objeto, no qual serão discriminados os resultados esperados e atingidos, os objetivos previstos e alcançados e os custos estimados e reais”; art. 97, § 1º: “a área técnica deverá indicar as metas ou as atividades descumpridas, recomendando a devolução dos recursos correspondentes”"}},{"codigo":"evidencias","descricao":"Fotografias e reportagens que comprovem a execução.","severidade":"bloqueio","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, parágrafo único, XI","citacao":"fotografias e reportagens que comprovem a execução do projeto"}},{"codigo":"cmd","descricao":"Produção médico-assistencial registrada exclusivamente no CMD também nos projetos antigos (antes, no CIHA).","severidade":"bloqueio","fonte":{"documento":"Portaria GM/MS 8.031/2025","dispositivo":"art. 3º"}},{"codigo":"pesquisa_autorizada","descricao":"Pesquisa com aprovação de CEP, Anvisa e CTNBio antes de começar.","severidade":"bloqueio","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 26, V","citacao":"“submeter o projeto à apreciação dos comitês de ética, da Agência Nacional de Vigilância Sanitária (ANVISA) e da Comissão Técnica Nacional de Biossegurança (CTNBio)”; “somente iniciar a execução do projeto após enviar ao Ministério da Saúde comprovante(s) de ter obtido as necessárias autorizações”"}},{"codigo":"insumos_remanescentes","descricao":"Insumos não usados vão ao ente que deu a anuência; para mantê-los, pedir ao gestor 30 dias antes do fim.","severidade":"alerta","parametros":{"diasAntes":30},"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 41, caput e § 2º, I","citacao":"art. 41: “adquiridos que não foram utilizados serão doados, ao término do projeto, ao ente federativo que anuiu com a realização do projeto”; § 2º, I: “nos 30 (trinta) dias anteriores ao término do projeto, solicitar à Secretaria de Saúde do ente federativo que anuiu com a realização do projeto a manutenção do uso dos produtos”","nota":"A permanência só vale para instituição que atue de forma complementar ao SUS, com termo de compromisso com o gestor (§ 2º, II)."}},{"codigo":"bens_permanentes","descricao":"Equipamentos e material permanente com identificação do projeto, inventário e destino no fim.","severidade":"alerta","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, parágrafo único, XII; art. 38","citacao":"art. 92, XII: “relação de equipamentos e materiais permanentes adquiridos para as atividades do projeto, contendo o número e/ou identificação do projeto e controlados em inventário físico específico”; art. 38: “será revertido, ao final do projeto, mediante doação, ao patrimônio do ente federativo que anuiu com a realização do projeto”","nota":"A instituição pode ficar com o bem se pedir ao gestor do SUS nos 30 dias anteriores ao término (art. 38, § 3º)."}},{"codigo":"dados_de_pacientes","descricao":"Dados de saúde são sensíveis: não vão prontuários ao sistema.","severidade":"alerta","fonte":{"documento":"Lei 13.709/2018 (LGPD)","dispositivo":"art. 5º, II; art. 11","nota":"O anexo anterior não trata de dados pessoais; criptografia e destruição ou devolução a pedido do MS são da minuta do Termo de 2025."}}],"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 97, caput, I e II; art. 96, § 1º; art. 31","citacao":"art. 97, I: “confirmação da apresentação dos documentos relacionados no art. 92, parágrafo único referente à análise da execução do objeto e dos objetivos do projeto”; art. 97, II: “comparação entre os resultados esperados e os atingidos pelo projeto”","nota":"O registro no CMD para os projetos antigos vem da Portaria GM/MS 8.031/2025, art. 3º."}},"divulgacao":{"lacuna":"norma_silente","motivo":"O anexo anterior não tem regras de divulgação, aprovação de peças nem logotipo; continua vedado dar ao doador vantagem em razão da doação.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"texto integral; arts. 44, IV, 105, X, e 110","nota":"O logotipo e a menção ao MS vêm da minuta do Termo de 2025; o Termo que o projeto assinou pode ter cláusula parecida."}},"envio":{"sistema":"AR, Sedex ou protocolo","descricao":"Prestação entregue por AR, Sedex ou protocolo, com os documentos do art. 92 e a auditoria independente.","documentos":[{"codigo":"relatorio_objeto","descricao":"Relatório de cumprimento do objeto","em":["parcial","final"],"obrigatorio":true,"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, I"}},{"codigo":"fisico_financeiro","descricao":"Relatório final de execução físico-financeira","em":["final"],"obrigatorio":true,"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, II"}},{"codigo":"receitas_despesas","descricao":"Relatório de execução de receitas e despesas","em":["final"],"obrigatorio":true,"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, III"}},{"codigo":"relacao_pagamentos","descricao":"Relação de pagamentos","em":["final"],"obrigatorio":true,"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, IV"}},{"codigo":"extrato","descricao":"Extrato da conta, do recebimento ao último pagamento","em":["final"],"obrigatorio":true,"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, V"}},{"codigo":"rendimentos","descricao":"Demonstrativo de rendimentos das aplicações","em":["final"],"obrigatorio":true,"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, VI"}},{"codigo":"gru","descricao":"Comprovante de recolhimento dos recursos não aplicados por GRU, quando houver","em":["final"],"obrigatorio":false,"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, VII"}},{"codigo":"volta_para_captacao","descricao":"Comprovante de transferência dos recursos não usados da Conta Movimento para a Captação, quando houver","em":["final"],"obrigatorio":false,"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, VIII"}},{"codigo":"comprovantes_despesa","descricao":"Cópia dos documentos comprobatórios das despesas","em":["final"],"obrigatorio":true,"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, IX"}},{"codigo":"bens","descricao":"Relação de bens adquiridos ou produzidos","em":["final"],"obrigatorio":true,"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, X"}},{"codigo":"fotos","descricao":"Fotografias e reportagens da execução","em":["final"],"obrigatorio":true,"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, XI"}},{"codigo":"equipamentos","descricao":"Relação de equipamentos e materiais permanentes, com identificação do projeto e inventário físico","em":["final"],"obrigatorio":true,"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, XII"}},{"codigo":"producao","descricao":"Informações de produção (CIHA; hoje, CMD)","em":["final"],"obrigatorio":true,"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, XIII","nota":"A Portaria GM/MS 8.031/2025, art. 3º, levou os projetos antigos para o CMD."}},{"codigo":"encerramento_conta","descricao":"Comprovante de encerramento da Conta Movimento","em":["final"],"obrigatorio":true,"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, XIV"}},{"codigo":"auditoria","descricao":"Demonstrações contábeis e financeiras com parecer conclusivo de auditoria independente (CRC)","em":["parcial","final"],"obrigatorio":true,"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, parágrafo único"}}],"modelos":[],"regras":[{"codigo":"modelos_do_anexo","descricao":"Documentos do art. 92 e modelos dos Anexos 1 a 10 do Anexo LXXXVI, com o Termo que o projeto assinou; os atos SE/MS de 2026 valem por decisão do MS.","severidade":"info","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 92, parágrafo único; Anexos 1 a 10","nota":"O Manual Orientativo da Portaria GM/MS 8.031/2025 é do Anexo LXXXVI-A."}}],"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"arts. 91 e 92"}},"posEnvio":{"resultados":[{"resultado":"aprovada","descricao":"Aplicação regular dos recursos e avaliação técnica satisfatória.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 98, § 1º","citacao":"O projeto será considerado aprovado integralmente quando o parecer técnico atestar a aplicação regular dos recursos e indicar que o projeto teve avaliação técnica satisfatória."}},{"resultado":"aprovada_ressalvas","descricao":"Contas regulares com avaliação técnica insatisfatória, sem prejuízo ao erário nem descumprimento do objeto; na execução parcial, o remanescente com rendimentos volta em 30 dias.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 98, § 2º; art. 102","citacao":"apesar de regulares as contas, tiver obtido avaliação técnica insatisfatória com fundamento nos aspectos do art. 97, desde que não resulte em prejuízo ao erário ou descumprimento do objeto"}},{"resultado":"reprovada","descricao":"Objeto descumprido ou contas irregulares, mesmo com avaliação técnica favorável; a omissão também reprova.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 98, §§ 3º e 4º; art. 101","citacao":"A omissão na prestação de contas também é causa de reprovação"}}],"devolucao":{"descricao":"GRU para a Conta Única do Tesouro, sem prejuízo ao benefício fiscal do doador, em 30 dias da notificação: saldo do orçamento, saldo ao fim da execução e reprovação parcial ou final.","atualizacao":"Na reprovação, o valor irregular é atualizado desde a captação pelo índice da caderneta de poupança.","gru":[],"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 88, V a VII e §§ 1º e 2º; art. 101"}},"regras":[{"codigo":"tce","descricao":"TCE por não aplicação ou aplicação incorreta, inclusive antes do fim da parceria, com registro no SIAFI.","severidade":"info","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 89, § 1º; arts. 101, § 2º, 108 e 109","citacao":"art. 89, § 1º: “A não aplicação sem justa causa ou aplicação incorreta dos recursos no âmbito do Pronon e do Pronas/PCD poderá ensejar instauração de Tomada de Contas Especial.”; art. 109: “o registro de seus atos será realizado no Sistema Integrado de Administração Financeira do Governo Federal (SIAFI)”"}},{"codigo":"omissao_sanavel","descricao":"A omissão pode ser sanada até o julgamento da TCE.","severidade":"info","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 98, § 4º","citacao":"A omissão na prestação de contas também é causa de reprovação, podendo ser sanada se apresentada até o julgamento da Tomada de Contas Especial."}},{"codigo":"analise_financeira_fns","descricao":"Superintendência Estadual do MS faz a análise contábil e financeira (AACF), que segue ao DESID e à área técnica, para o parecer conclusivo.","severidade":"info","fonte":{"documento":"Manual de análise contábil e financeira PRONON e PRONAS/PCD (FNS, 2019), Anexo III","dispositivo":"seções 1.0 e 6.0, p. 5 e 7"}},{"codigo":"inabilitacao","descricao":"Inabilitação pelos critérios do art. 105 do regime anterior.","severidade":"alerta","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 105"}}],"fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"arts. 96 a 109","citacao":"art. 96: “realizar a análise das atividades executadas, com emissão de parecer conclusivo do relatório em até 90 (noventa) dias, contados da data de recebimento”"}},"guarda":{"marco":"registro_decisao","quantidade":5,"unidade":"anos","prorrogaParaDiaUtil":false,"descricao":"Documentos guardados por 5 anos a partir da aprovação da prestação de contas.","fonte":{"documento":"Anexo LXXXVI da PRC 5/2017 (revogado)","dispositivo":"art. 95"}}}$regime$::jsonb as p) dados
on conflict (codigo, versao) do nothing;

-- Audiovisual (ANCINE) — IN 150/2019 (versão 2)
update public.prestacao_regimes set status = 'obsoleto'
where codigo = 'ancine_in150_2019' and versao < 2 and status = 'publicado';

insert into public.prestacao_regimes
  (codigo, versao, nome, area, mecanismo, esfera, orgao, sistema_oficial, norma_referencia,
   vigente_desde, vigente_ate, status, parametros, fontes, checklist_envio, modelos_saida, publicado_em)
select
  'ancine_in150_2019', 2, 'Audiovisual (ANCINE) — IN 150/2019', 'audiovisual', 'audiovisual',
  'federal', 'ANCINE', 'STR e Protocolo Digital', 'Lei 8.685/1993; Lei 8.313/1991, arts. 18 e 25; MP 2.228-1/2001; IN ANCINE 150/2019 (despesas a partir de 2020; antes, IN 124/2015); IN ANCINE 125/2015 (aprovação e acompanhamento)',
  '2020-01-01'::date, '2022-01-16'::date, 'publicado',
  p, coalesce(p->'fontes', '[]'), coalesce(p->'envio'->'documentos', '[]'), coalesce(p->'envio'->'modelos', '[]'), now()
from (select $regime${"codigo":"ancine_in150_2019","versao":2,"nome":"Audiovisual (ANCINE) — IN 150/2019","area":"audiovisual","mecanismo":"audiovisual","esfera":"federal","orgao":"ANCINE","sistemaOficial":"STR e Protocolo Digital","normaReferencia":"Lei 8.685/1993; Lei 8.313/1991, arts. 18 e 25; MP 2.228-1/2001; IN ANCINE 150/2019 (despesas a partir de 2020; antes, IN 124/2015); IN ANCINE 125/2015 (aprovação e acompanhamento)","vigenteDesde":"2020-01-01","identificadorOficial":{"tipo":"salic","rotulo":"SALIC"},"fontes":[{"documento":"Manuais de prestação de contas (ANCINE)","url":"https://www.gov.br/ancine/pt-br/assuntos/atribuicoes-ancine/fomento/prestacao-de-contas/manuais"},{"documento":"IN ANCINE 159/2021, art. 63 (transição)","url":"https://www.gov.br/ancine/pt-br/acesso-a-informacao/legislacao/instrucoes-normativas/instrucao-normativa-no-159"}],"aplicabilidade":{"criterio":"aprovacao_projeto","desde":null,"ate":"2022-01-16","descricao":"Projetos aprovados antes de 17/01/2022, com despesas a partir de 01/01/2020 pela IN 150; despesas anteriores seguem a IN 124/2015.","sucede":[],"fonte":{"documento":"Manual de Prestação de Contas ANCINE v2.11 (23/09/2026)","dispositivo":"p. 4; IN 159, art. 63; IN 150, arts. 66, 73 e 75","nota":"A IN 150 revoga a IN 124/2015, a norma de prestação de contas anterior, e vale para despesas a partir de 1º/1/2020."}},"prazos":{"prestacaoFinal":{"descricao":"Prestação de contas final, contada da conclusão do objeto (CPB, lançamento comercial, último dia do festival ou entrega do desenvolvimento)","responsavel":"proponente","marco":"conclusao_objeto","quantidade":180,"unidade":"dias_corridos","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 3º, caput e parágrafo único; arts. 4º e 5º","citacao":"A prestação de contas final dos projetos realizados com recursos de fomento indireto deverá ser apresentada à ANCINE em até 180 (cento e oitenta) dias da conclusão do objeto do projeto."}},"fimExecucaoFinanceira":{"descricao":"Última despesa do projeto (fim da execução financeira)","responsavel":"proponente","marco":"conclusao_objeto","quantidade":180,"unidade":"dias_corridos","fonte":{"documento":"IN ANCINE 158/2021","dispositivo":"art. 57; FAQ SPR 2.10","aConfirmar":true,"nota":"Vale a IN 158/2021 se a regra de transição dela alcançar o projeto; senão, a IN 125/2015, norma de aprovação que a IN 150 cita (Anexo, art. 1º, VIII)."}},"respostaDiligencia":{"descricao":"Atender diligência, da confirmação de recebimento; prorrogável uma vez por 30 dias a pedido justificado","responsavel":"proponente","marco":"ciencia_diligencia","quantidade":30,"unidade":"dias_corridos","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 46, caput e §§ 1º a 3º","citacao":"terão o prazo de atendimento fixado em 30 (trinta) dias a partir da data da confirmação de seu recebimento pela proponente. […] poderá conceder prorrogação única de 30 (trinta) dias do prazo fixado no caput deste artigo."}},"notificacaoOmissao":{"descricao":"Apresentar a prestação omitida depois da notificação, sob pena de TCE ou cobrança","responsavel":"proponente","marco":"ciencia_diligencia","quantidade":30,"unidade":"dias_corridos","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 6º, §§ 1º e 2º","citacao":"A proponente será notificada de sua inscrição na situação de inadimplência e instada a regularizar a omissão no prazo de 30 (trinta) dias."}},"analisePrestacao":{"lacuna":"norma_silente","motivo":"A IN 150 não fixa prazo para a ANCINE analisar a prestação.","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"Seção V (arts. 26 a 31); texto integral"}},"analiseAcompanhamento":{"descricao":"Análise de pedido de acompanhamento (remanejamento, prorrogação), interrompida por diligência","responsavel":"orgao","marco":"protocolo_alteracao","quantidade":90,"unidade":"dias_corridos","fonte":{"documento":"IN ANCINE 158/2021","dispositivo":"art. 3º, II e § 3º","aConfirmar":true,"nota":"Vale a IN 158/2021 se a regra de transição dela alcançar o projeto; senão, a IN 125/2015, norma de aprovação que a IN 150 cita (Anexo, art. 1º, VIII)."}},"recurso":{"descricao":"Recurso com efeito suspensivo, do recebimento da notificação; última instância é a Diretoria Colegiada","responsavel":"proponente","marco":"ciencia_decisao","quantidade":30,"unidade":"dias_corridos","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 49; art. 51","citacao":"Caberá recurso contra as decisões exaradas pela Diretoria Colegiada da ANCINE, no prazo de 30 (trinta) dias, contado da data do recebimento da notificação, sendo o mesmo recebido com efeito suspensivo."}},"devolucao":{"descricao":"Pagar a GRU da glosa ou do débito, calculada pela ANCINE","responsavel":"proponente","marco":"ciencia_decisao","quantidade":30,"unidade":"dias_corridos","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 41, caput","citacao":"Decorrido o prazo de 30 (trinta) dias da data de recebimento da Guia de Recolhimento da União - GRU e permanecendo a proponente omissa quanto ao seu recolhimento integral, apresentação de recurso ou solicitação de parcelamento"}},"correcaoLogomarcaInfraestrutura":{"descricao":"Corrigir a placa de infraestrutura depois da decisão","responsavel":"proponente","marco":"ciencia_decisao","quantidade":30,"unidade":"dias_corridos","fonte":{"documento":"IN ANCINE 130/2016, com a IN 152/2020","dispositivo":"art. 9º","nota":"A IN 150 remete à norma de logomarca (art. 43, § 3º)."}}},"prestacaoParcial":{"modalidades":["a_criterio_do_orgao"],"descricao":"A ANCINE pode pedir prestação parcial conforme o regramento do projeto, com os documentos do Anexo menos os incisos IV e V; a análise parcial vai à Diretoria Colegiada, e as despesas da parcial não são reanalisadas na final.","prazo":null,"regras":[{"codigo":"sem_gru_nem_encerramento","descricao":"A parcial dispensa os comprovantes de recolhimento e de encerramento das contas.","severidade":"info","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"Anexo, art. 1º, § 2º","citacao":"A prestação de contas parcial prescinde dos documentos dos incisos IV e V.","nota":"Na IN 150 a dispensa da parcial é o Anexo, art. 1º, § 2º."}},{"codigo":"extratos_ate_a_data","descricao":"Na parcial, os extratos vão da abertura da conta até a data da prestação.","severidade":"alerta","fonte":{"documento":"Manual de Prestação de Contas ANCINE v2.11 (23/09/2026)","dispositivo":"p. 18, nota 3","nota":"A IN 150 só descreve os extratos da abertura ao encerramento; o recorte da parcial é do Manual."}},{"codigo":"sem_reanalise_na_final","descricao":"Despesas e documentos da prestação parcial não são reanalisados na final.","severidade":"info","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 58","citacao":"As despesas executadas e seus documentos fiscais comprobatórios da execução do projeto, integrantes da prestação de contas parcial, não serão objeto de nova análise quando da prestação de contas final."}},{"codigo":"fsa_especial","descricao":"A prestação especial do contrato FSA segue as regras da parcial.","severidade":"info","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 59","citacao":"Os regramentos para prestação de contas parcial aplicam-se, subsidiariamente, à prestação de contas especial prevista nos contratos do Fundo Setorial do Audiovisual"}}],"fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"arts. 56 a 59; Anexo, art. 1º, § 2º","citacao":"A ANCINE poderá solicitar prestação de contas parcial baseada nas especificidades e na fase de execução de cada projeto, conforme determinado em regramento específico."}},"orcamento":{"estrutura":{"niveis":["Item orçamentário (IV.a e IV.b do DO)","Item"],"descricao":"Orçamento analítico aprovado por item; o DO compara o aprovado com o captado por fonte e com o executado. Tributos retidos e encargos entram na rubrica do fato gerador.","fonte":{"documento":"Manual de Prestação de Contas ANCINE v2.11 (23/09/2026)","dispositivo":"p. 12 e 60; Demonstrativo Orçamentário e Financeiro, seção IV","nota":"A IN 150 só exige o DO; a estrutura vem do Manual."}},"grupos":[{"codigo":"execucao","rotulo":"Itens do projeto","descricao":"Itens financiáveis de desenvolvimento, produção, distribuição ou da modalidade.","fonte":{"documento":"IN ANCINE 158/2021","dispositivo":"art. 31","aConfirmar":true,"nota":"Vale a IN 158/2021 se a regra de transição dela alcançar o projeto; senão, a IN 125/2015, norma de aprovação que a IN 150 cita (Anexo, art. 1º, VIII)."}},{"codigo":"gerenciamento","rotulo":"Gerenciamento","descricao":"Gerenciamento da produção, com toda a infraestrutura; só produtora brasileira.","fonte":{"documento":"IN ANCINE 158/2021","dispositivo":"art. 31, I","aConfirmar":true,"nota":"Vale a IN 158/2021 se a regra de transição dela alcançar o projeto; senão, a IN 125/2015, norma de aprovação que a IN 150 cita (Anexo, art. 1º, VIII). A IN 150 só veda pagá-lo a radiodifusoras e afins (art. 21, XIX)."}},{"codigo":"agenciamento","rotulo":"Agenciamento","descricao":"Agenciamento de captação pela Lei 8.313 e pelo art. 1º-A da Lei 8.685.","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 21, IV, a","citacao":"para captação de recursos em mecanismos diferentes do art. 1º-A da Lei nº 8.685/93 e da Lei nº 8.313/91;","nota":"A IN 150 só admite agenciamento nesses dois mecanismos; a definição do grupo vem da norma de aprovação."}},{"codigo":"colocacao","rotulo":"Coordenação e colocação","descricao":"Coordenação e colocação de certificados do art. 1º da Lei 8.685 (taxas, prospecto, agente divulgador).","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 21, V","citacao":"ou para a captação de recursos em mecanismos diferentes do art. 1º da Lei nº 8.685/93;","nota":"A composição (taxas, prospecto, agente divulgador) vem da norma de aprovação."}}],"bases":{"orcamento_producao":{"descricao":"Orçamento de produção: os itens do projeto, sem gerenciamento, agenciamento e colocação.","soma":"todos","exceto":["gerenciamento","agenciamento","colocacao"],"fonte":{"documento":"IN ANCINE 158/2021","dispositivo":"art. 31, I","aConfirmar":true,"nota":"Vale a IN 158/2021 se a regra de transição dela alcançar o projeto; senão, a IN 125/2015, norma de aprovação que a IN 150 cita (Anexo, art. 1º, VIII). A fonte não detalha o que entra no orçamento de produção; o limite também se prende ao executado com recursos ANCINE."}},"valor_total_projeto":{"descricao":"Orçamento global aprovado.","soma":"todos","exceto":[],"fonte":{"documento":"Manual de Prestação de Contas ANCINE v2.11 (23/09/2026)","dispositivo":"p. 27–28","nota":"A IN 150 usa \"orçamento global aprovado\" (art. 14, parágrafo único) sem defini-lo como base."}}},"tetos":[{"codigo":"gerenciamento","descricao":"Gerenciamento","grupos":["gerenciamento"],"percentual":10,"base":"orcamento_producao","severidade":"bloqueio","fonte":{"documento":"IN ANCINE 158/2021","dispositivo":"art. 31, I; Lei 11.437/2006, art. 12","aConfirmar":true,"nota":"A IN 150 glosa o excesso (art. 21, VI) sem fixar percentual nem base. Vale a IN 158/2021 se a regra de transição dela alcançar o projeto; senão, a IN 125/2015, norma de aprovação que a IN 150 cita (Anexo, art. 1º, VIII). Limitado ao executado com recursos ANCINE; na coprodução internacional, só a parte brasileira. O excesso é glosado (IN 159, art. 18, VI)."}},{"codigo":"agenciamento","descricao":"Agenciamento","grupos":["agenciamento"],"percentual":10,"base":"valor_autorizado_captacao","proporcionalAoCaptado":true,"severidade":"bloqueio","fonte":{"documento":"IN ANCINE 158/2021","dispositivo":"art. 31, II","aConfirmar":true,"nota":"A IN 150 glosa o excesso (art. 21, VI) sem fixar percentual nem base. Vale a IN 158/2021 se a regra de transição dela alcançar o projeto; senão, a IN 125/2015, norma de aprovação que a IN 150 cita (Anexo, art. 1º, VIII). Proporcional ao captado: R$ 100 mil autorizados e R$ 80 mil captados dão teto de R$ 8 mil."}},{"codigo":"colocacao","descricao":"Coordenação e colocação","grupos":["colocacao"],"percentual":10,"base":"valor_autorizado_captacao","proporcionalAoCaptado":true,"severidade":"bloqueio","fonte":{"documento":"IN ANCINE 158/2021","dispositivo":"art. 31, III","aConfirmar":true,"nota":"A IN 150 glosa o excesso (art. 21, VI) sem fixar percentual nem base. Vale a IN 158/2021 se a regra de transição dela alcançar o projeto; senão, a IN 125/2015, norma de aprovação que a IN 150 cita (Anexo, art. 1º, VIII). Sobre o autorizado pelo art. 1º da Lei 8.685, limitado ao captado."}}],"regras":[{"codigo":"contrapartida_minima","descricao":"Contrapartida de ao menos 5% do orçamento global aprovado quando há mecanismo da Lei do Audiovisual.","severidade":"bloqueio","parametros":{"percentual":5},"fonte":{"documento":"Lei 8.685/1993","dispositivo":"art. 4º, § 2º, I; IN 150, art. 2º, II, e art. 17","nota":"A alternativa de 5% das fontes brasileiras integralizadas é da IN 159 (art. 16, § 1º)."}},{"codigo":"agenciamento_vedado","descricao":"Agenciamento glosado fora do art. 1º-A da Lei 8.685 e da Lei 8.313 e na captação em editais e outras seleções públicas (inclusive programas internacionais) ou feita por estatais.","severidade":"bloqueio","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 21, IV, a e b","citacao":"para captação de recursos provenientes de editais ou qualquer outro mecanismo de seleção pública, incluindo programas internacionais com participação do Ministério da Cidadania e ANCINE, ou realizada por empresas estatais"}},{"codigo":"colocacao_autorizada","descricao":"Coordenação e colocação só por agente autorizado na CVM e para o art. 1º da Lei 8.685.","severidade":"bloqueio","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 21, V","citacao":"pagamento de Coordenação e Colocação para agentes não autorizados ou registrados na CVM"}},{"codigo":"gerenciamento_por_quem","descricao":"Gerenciamento não pode ser pago a radiodifusoras, programadoras, distribuidoras ou telefônicas.","severidade":"bloqueio","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 21, XIX","citacao":"pagamento de serviço de gerenciamento a empresa de serviços de radiodifusão de sons e imagens, empresas de comunicação eletrônica de massa por assinatura, distribuidoras cinematográficas, de vídeo ou de programas de televisão","nota":"A IN 150 fala em empresas de comunicação eletrônica de massa por assinatura, inclusive telefonia fixa e móvel."}}]},"alteracoes":{"janela":{"aPartirDe":null,"ate":"fim_execucao","descricao":"Durante a execução; o pedido prévio vai à Superintendência de Fomento (SFO).","fonte":{"documento":"Manual de Prestação de Contas ANCINE v2.11 (23/09/2026)","dispositivo":"p. 27–28","nota":"A IN 150 não trata de pedidos durante a execução; vale o Manual."}},"tipos":{"remanejamento":{"permitido":true,"classificacao":"administrativa","condicoes":[{"tipo":"movido_ate","percentual":20,"base":"valor_total_projeto","acumulado":true,"descricao":"O conjunto de alterações (extrapolações mais rubricas novas) fica abaixo de 20% do orçamento global aprovado.","fonte":{"documento":"Manual de Prestação de Contas ANCINE v2.11 (23/09/2026)","dispositivo":"p. 27–28","nota":"A IN 150 não fixa os 20%; trata o remanejamento irregular como ressalva (art. 29, V). Vale para projetos fora dos limites de grandes itens da IN 158 (arts. 49 e 50)."}}],"requisitos":[{"tipo":"tetos","severidade":"bloqueio","descricao":"Gerenciamento, agenciamento e colocação continuam dentro dos limites.","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 21, VI","citacao":"pagamentos que excedam os percentuais fixados legalmente para rubricas orçamentárias, tais como o de gerenciamento e execução, agenciamento, coordenação e colocação, dentre outras;"}}],"orientacoes":[{"codigo":"justificar_na_pc","descricao":"Sem dever de justificar cada alteração: remanejamento em desacordo leva a ressalva e advertência, e despesa não autorizada é glosada na análise final; o DO pede justificativa das significativas diferenças.","severidade":"alerta","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 29, V; art. 21, XV; art. 43, § 1º, I","citacao":"despesas que tenham sido anteriormente glosadas ou não autorizadas pela ANCINE do orçamento em sede de análise de execução final e cumprimento de objeto;"}}],"fonte":{"documento":"Manual de Prestação de Contas ANCINE v2.11 (23/09/2026)","dispositivo":"p. 27–28","nota":"A IN 150 só trata do remanejamento irregular como ressalva (art. 29, V)."}},"complementacao":{"permitido":true,"classificacao":"formal","condicoes":[],"requisitos":[{"tipo":"tetos","severidade":"bloqueio","descricao":"O redimensionamento respeita os limites.","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 21, VI","citacao":"pagamentos que excedam os percentuais fixados legalmente para rubricas orçamentárias, tais como o de gerenciamento e execução, agenciamento, coordenação e colocação, dentre outras;"}}],"orientacoes":[],"fonte":{"documento":"Guia de Acompanhamento de Projetos do FSA (BRDE, jan/2025)","dispositivo":"§ 4.10; IN 158, arts. 49 e 50","aConfirmar":true,"nota":"A IN 150 não regula a complementação; vale o Guia do FSA e a norma de acompanhamento. Redimensionamento do orçamento depende de aprovação prévia; o texto da IN 158 não foi lido."}},"reducao":{"permitido":true,"classificacao":"formal","condicoes":[],"requisitos":[{"tipo":"tetos","severidade":"alerta","descricao":"Depois da redução, os grupos continuam dentro dos limites.","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"Anexo, art. 1º, VII; art. 21, VI","citacao":"com subsequente adaptação dos valores de contrapartida obrigatória e de remuneração pelos serviços de agenciamento e de gerenciamento e execução do projeto","nota":"Na redução, contrapartida, agenciamento e gerenciamento acompanham o novo orçamento."}}],"orientacoes":[],"fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"Anexo, art. 1º, VII","citacao":"solicitação de redução do orçamento global do projeto aprovado, para os valores efetivamente executados, […] para os projetos oriundos de incentivo fiscal, quando de interesse da proponente;","nota":"No incentivo fiscal, a redução aos valores executados vai junto com a prestação, sem aprovação prévia; no FSA e no fomento direto, segue o Guia do FSA e o contrato."}},"inclusao":{"permitido":true,"classificacao":"administrativa","condicoes":[{"tipo":"movido_ate","percentual":20,"base":"valor_total_projeto","acumulado":true,"descricao":"Rubricas novas e extrapolações, somadas, ficam abaixo de 20% do orçamento global aprovado.","fonte":{"documento":"Manual de Prestação de Contas ANCINE v2.11 (23/09/2026)","dispositivo":"p. 27–28","nota":"A IN 150 não fixa os 20% para rubricas novas."}}],"requisitos":[{"tipo":"tetos","severidade":"bloqueio","descricao":"Com a rubrica nova, os limites continuam respeitados.","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 21, VI","citacao":"pagamentos que excedam os percentuais fixados legalmente para rubricas orçamentárias, tais como o de gerenciamento e execução, agenciamento, coordenação e colocação, dentre outras;"}}],"orientacoes":[{"codigo":"justificar_na_pc","descricao":"Sem dever de justificar cada rubrica nova: despesa não autorizada é glosada na análise final, e remanejamento em desacordo leva a ressalva.","severidade":"alerta","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 29, V; art. 21, XV; art. 43, § 1º, I","citacao":"despesas que tenham sido anteriormente glosadas ou não autorizadas pela ANCINE do orçamento em sede de análise de execução final e cumprimento de objeto;"}}],"fonte":{"documento":"Manual de Prestação de Contas ANCINE v2.11 (23/09/2026)","dispositivo":"p. 27–28","nota":"A IN 150 não trata da inclusão."}}},"alertasPorItem":[],"prazoAnalise":"analiseAcompanhamento","silencioAprova":false,"regras":[{"codigo":"projeto_tecnico","descricao":"Alterar o projeto técnico sem autorização prévia leva a inabilitação.","severidade":"bloqueio","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 29, XI; art. 43, § 1º, II, b","citacao":"efetuar alterações nos parâmetros técnicos aprovados para o produto final do projeto sem a prévia autorização da ANCINE […] b) a ocorrência do inciso XI do art. 29;"}},{"codigo":"fsa","descricao":"No FSA: abaixo de 20%, sem aprovação prévia e justificado na prestação; acima ou redimensionamento, pela CUP (grandes itens) ou protocolo digital (orçamento detalhado).","severidade":"info","fonte":{"documento":"Guia de Acompanhamento de Projetos do FSA (BRDE, jan/2025)","dispositivo":"§ 4.10","nota":"A IN 150 não trata de alterações no FSA."}}],"fonte":{"documento":"Manual de Prestação de Contas ANCINE v2.11 (23/09/2026)","dispositivo":"p. 20 e 27–28","nota":"A IN 150 não trata de prazo de análise nem de aprovação tácita de alterações."}},"fornecedores":{"limites":[{"codigo":"concentracao","descricao":"Concentração em um mesmo fornecedor ou grupo ligado a um mesmo sócio, sobre o total executado","escopo":"fornecedor","base":"valor_executado","faixas":[{"percentual":25,"severidade":"alerta","consequencia":"Advertência e aprovação com ressalvas"},{"percentual":50,"severidade":"bloqueio","consequencia":"Inabilitação por até 2 anos"}],"excecoes":[{"descricao":"Animação","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 29, VI, f; art. 43, § 1º, II, c","citacao":"exceto para projetos específicos de: […] f) animação;"}},{"descricao":"Jogos eletrônicos","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 29, VI, h; art. 43, § 1º, II, c","citacao":"exceto para projetos específicos de: […] h) jogos eletrônicos."}},{"descricao":"Produção com orçamento executado de até R$ 500 mil","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 29, VI, g; art. 43, § 1º, II, c","citacao":"g) produção com orçamento executado de até R$ 500.000,00 (quinhentos mil reais);"}},{"descricao":"Desenvolvimento","fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"art. 29, VI, a; art. 43, § 1º, II, c