o","descricao":"Objeto concluído em 36 meses (animação acima de 70 min), 24 (demais produções) ou 12 (desenvolvimento, distribuição e festival), da 1ª liberação.","severidade":"info","parametros":{"animacao":36,"producao":24,"outros":12},"fonte":{"documento":"IN ANCINE 158/2021","dispositivo":"art. 53","aConfirmar":true,"nota":"Vale a IN 158/2021 se a regra de transição dela alcançar o projeto; senão, a IN 125/2015, norma de aprovação que a IN 150 cita (Anexo, art. 1º, VIII)."}}],"fonte":{"documento":"IN ANCINE 150/2019","dispositivo":"Anexo, art. 1º, VIII; art. 71; art. 3º, parágrafo único","citacao":"material comprobatório de cumprimento do objeto e finalidade, conforme previsto na Instrução Normativa n.º 125, de 22 de dezembro de 2015.","nota":"A lista por modalidade da IN 125, art. 85, não foi conferida."}},"divulgacao":{"marcas":["ANCINE","FSA e agente financeiro (com FSA)","Bandeira Nacional"],"aprovacaoPrevia":{"exigida":false,"prazo":null,"silencioAprova":false,"descricao":"Não é preciso aprovar antes: a aplicação da logomarca é verificada na análise do objeto.","fonte":{"documento":"Manual de Aplicação da Logomarca v3.0 (24/08/2022)","dispositivo":"aprovação prévia","nota":"A IN 150 não trata; vale o manual da logomarca."}},"defeso":null,"regras":[{"codigo":"onde_aplicar","descricao":"Logomarca nos créditos iniciais e no cartaz (desenvolvimento, produção, finalização), no cartaz (distribuição), em cartazes, vinheta e catálogo (festival) e na placa (infraestrutura).","severidade":"bloqueio","fonte":{"documento":"IN ANCINE 130/2016, com a IN 152/2020","dispositivo":"art. 4º (red. IN 152/2020)","nota":"A IN 150 remete à norma de logomarca (art. 29, XII), na redação vigente na data."}},{"codigo":"bandeira","descricao":"Bandeira Nacional em todo material de divulgação impresso, virtual ou audiovisual, salvo memes e vídeos curtos.","severidade":"bloqueio","fonte":{"documento":"Lei 5.700/1971","dispositivo":"art. 3º-A; IN 152/2020","nota":"A IN 150 não trata; vale